"""Size-capped LRU filesystem tier with worker-executed, per-rank I/O.

Two deliberate departures from the stock ``fs`` tier:

1. **A byte cap with LRU eviction.** The stock tier never deletes, so it
   cannot be pointed at a directory that shares a filesystem with anything
   else. The cap here is per rank directory: every rank keeps the same block
   set, each ``max_bytes`` large, on its own node-local disk.

2. **The scheduler process never moves bytes.** The stock tier reads and
   writes the scheduler's mmap of the shared offload region, which silently
   assumes every rank shares that mmap — only true when all ranks live on the
   scheduler's node. On a multi-node TP deployment (Ray), a remote rank's
   slice was never persisted and a promotion never reached the remote rank's
   mmap, so restored-from-disk KV was garbage on that rank (measured: 0/8
   needle recall vs 8/8 fresh, at 100%% reported hit rate). This manager only
   tracks state and makes decisions; the byte movement ships to every worker
   as ``DiskJobDirective`` entries in the per-step connector metadata (see
   ``tiering/fs/distributed.py``), and each rank reads/writes only its own
   slice under its own ``<base>_r<rank>`` directory. A job finishes when all
   ranks have reported it.

Config (secondary_tiers entry)::

    {"type": "fs_lru", "root_dir": "/mnt/ds4-kvcache", "max_bytes": 16106127360}

Failure and races stay benign by construction. A block evicted while a load
is in flight makes that rank's read fail; the job is reported unsuccessful,
the offloading manager treats it as a miss and recomputes, and the key is
deregistered everywhere. Correctness never depends on a cached block still
being present — on any rank.

The cap is a high-water bound, not an instantaneous one: the blocks of the
store that triggers an eviction are never evicted to make room for
themselves, so a rank directory can exceed ``max_bytes`` by at most one store
batch before settling.
"""

import hashlib
import json
import os
from collections import OrderedDict
from collections.abc import Iterable
from dataclasses import dataclass
from typing import TYPE_CHECKING

from typing_extensions import override

from vllm.logger import init_logger
from vllm.v1.kv_offload.base import (
    OffloadKey,
    ReqContext,
    get_offload_block_hash,
    get_offload_group_idx,
)
from vllm.v1.kv_offload.file_mapper import FileMapper
from vllm.v1.kv_offload.tiering.base import (
    JobMetadata,
    JobResult,
    RequestOffloadingContext,
    SecondaryTierManager,
)
from vllm.v1.kv_offload.tiering.fs.distributed import (
    CONFIG_DIGEST_LEN,
    DiskJobDirective,
    rank_base_dir,
    rel_block_path,
)

if TYPE_CHECKING:
    from vllm.v1.kv_offload.base import OffloadingSpec

logger = init_logger(__name__)

# Block states tracked per relative path.
_STORING = 0  # store job in flight on the workers; not yet loadable
_READY = 1  # present on every rank (or adopted from disk); loadable


@dataclass(slots=True)
class _PendingJob:
    is_load: bool
    rel_paths: list[str]
    reports: int = 0
    failures: int = 0


class LRUFileSystemTierManager(SecondaryTierManager):
    """Scheduler-side control plane of the distributed disk tier."""

    def __init__(
        self,
        offloading_spec: "OffloadingSpec",
        primary_kv_view: memoryview,
        tier_type: str,
        root_dir: str,
        max_bytes: int,
        n_read_threads: int = 8,
        n_write_threads: int = 8,
    ):
        """
        Args:
            root_dir: Root directory for block files (per node).
            max_bytes: Cap on the bytes of block files kept in each rank's
                directory. Rounded down to a whole number of blocks.
            n_read_threads / n_write_threads: sizes of each WORKER's I/O
                pool; this process does no I/O. Recorded here because the
                tier config is the single place both sides read.
        """
        super().__init__(offloading_spec, primary_kv_view, tier_type)

        parallel = offloading_spec.vllm_config.parallel_config
        self._num_workers: int = parallel.world_size
        # Per-rank slice of one offloaded block row. This is what each block
        # file holds, so it is also the accounting unit for the cap.
        self._slice_bytes: int = offloading_spec.cpu_page_size_per_worker
        assert self._slice_bytes > 0
        assert primary_kv_view.strides is not None
        assert self._slice_bytes * self._num_workers <= primary_kv_view.strides[0]

        # Rank directories are derived only from root_dir + model name +
        # rank — values every process reads from the same literal source.
        # The run-config digest goes into the RELATIVE paths instead, which
        # only this process generates, so a config change (dtype, block
        # sizes, groups) moves the namespace with no cross-process agreement
        # needed. FileMapper is used purely as the field assembler here; its
        # base-path digest is NOT (scheduler and workers resolve some fields
        # differently, so their digests disagree — measured on the dtype).
        model_name = offloading_spec.vllm_config.model_config.model
        run_config = FileMapper.from_offloading_spec(
            root_dir=root_dir,
            offloading_spec=offloading_spec,
            gpu_blocks_per_file=offloading_spec.block_size_factor,
            parallel_agnostic=False,
        ).get_run_config()
        canonical = json.dumps(run_config, sort_keys=True, separators=(",", ":"))
        self._cfg_prefix = hashlib.sha256(canonical.encode()).hexdigest()[
            :CONFIG_DIGEST_LEN
        ]
        # The scheduler shares its node with rank 0's worker; that directory
        # is the one this process seeds from.
        self._local_base_dir = rank_base_dir(root_dir, model_name, parallel.rank)

        self._root_dir = root_dir
        self._max_bytes = int(max_bytes)
        if self._max_bytes < self._slice_bytes:
            raise ValueError(
                f"max_bytes ({self._max_bytes}) is smaller than one "
                f"{self._slice_bytes}-byte block slice"
            )

        # Human-readable record of what each namespace digest means. Lives
        # OUTSIDE the rank directories so adoption never walks it.
        safe_model = model_name.replace("/", "_")
        config_path = os.path.join(
            root_dir, f"{safe_model}_config", f"{self._cfg_prefix}.json"
        )
        os.makedirs(os.path.dirname(config_path), exist_ok=True)
        if not os.path.exists(config_path):
            with open(config_path, "w") as f:
                json.dump(run_config, f, indent=2, sort_keys=True)

        # rel_path -> state, ordered least-recently-used first.
        self._lru: OrderedDict[str, int] = OrderedDict()
        self._bytes = 0
        self._evicted = 0

        # rel_path -> number of in-flight load jobs reading it. Guards the
        # evictor: deleting a file mid-promotion would fail the whole load.
        self._load_refs: dict[str, int] = {}

        # Directives waiting to be drained into the next step's connector
        # metadata, and job completions waiting for the manager's poll.
        self._directives: list[DiskJobDirective] = []
        self._files_to_remove: list[str] = []
        self._pending_jobs: dict[int, _PendingJob] = {}
        self._finished: list[JobResult] = []

        # Hit accounting. vLLM's own external_prefix_cache_* counters describe
        # what the *scheduler* concluded, which is not the same question as
        # whether this tier had the block: a lookup answered "storing, retry"
        # is neither a hit nor a miss upstream, and that distinction is
        # exactly what you need when a populated cache reports zero hits.
        self._lookup_hits = 0
        self._lookup_misses = 0
        self._lookup_pending = 0
        self._loaded_blocks = 0
        # req_id -> (hits, misses, pending) at request start
        self._req_marks: dict[str, tuple[int, int, int]] = {}

        self._seed_from_disk()

    # -- internals ---------------------------------------------------------

    def _rel_path(self, key: OffloadKey) -> str:
        return rel_block_path(
            self._cfg_prefix,
            get_offload_block_hash(key),
            get_offload_group_idx(key),
        )

    def _seed_from_disk(self) -> None:
        """Adopt block files left by an earlier run, oldest first.

        Only this node's rank directory is visible here; remote ranks are
        assumed to hold the same set. Where they diverged (a crash between
        deletes), the load for the missing block fails on that rank and the
        key degrades to a miss — correctness does not depend on the
        assumption holding.
        """
        found: list[tuple[float, str, int]] = []
        skipped = 0
        for dirpath, _, filenames in os.walk(self._local_base_dir):
            for name in filenames:
                path = os.path.join(dirpath, name)
                try:
                    st = os.stat(path)
                except OSError:
                    continue
                # Adopt only things that are the right size to *be* a block
                # slice. Everything adopted is counted against the cap and is
                # a candidate for deletion once it becomes the LRU victim, so
                # a foreign file would be silently deleted — and a full-row
                # file from the pre-distributed format would be silently
                # served with wrong geometry.
                if st.st_size != self._slice_bytes:
                    skipped += 1
                    continue
                found.append((st.st_mtime, path, st.st_size))

        if skipped:
            logger.warning(
                "fs_lru: ignoring %d file(s) under %s that are not %d-byte "
                "block slices. This tier owns its rank directory; nothing "
                "else should write there. (Files from the old whole-row "
                "format are also skipped — clear the directory to reclaim "
                "the space.)",
                skipped,
                self._local_base_dir,
                self._slice_bytes,
            )

        for _, path, size in sorted(found):
            rel = os.path.relpath(path, self._local_base_dir)
            self._lru[rel] = _READY
            self._bytes += size

        if found:
            logger.info(
                "fs_lru: adopted %d existing blocks (%.2f GiB per rank) "
                "under %s",
                len(found),
                self._bytes / (1 << 30),
                self._local_base_dir,
            )
        self._evict(keep=frozenset())

    def _evict(self, keep: frozenset[str]) -> None:
        """Queue deletions of least-recently-used blocks until the cap holds.

        ``keep`` names blocks that must survive — the ones being written by
        the store that triggered this eviction. Blocks still storing or with
        loads in flight are skipped too; they are transiently over-cap.
        """
        if self._bytes <= self._max_bytes:
            return
        victims: list[str] = []
        overflow = self._bytes - self._max_bytes
        for rel, state in self._lru.items():
            if overflow <= 0:
                break
            if rel in keep or state == _STORING or self._load_refs.get(rel):
                continue
            victims.append(rel)
            overflow -= self._slice_bytes
        for rel in victims:
            del self._lru[rel]
            self._bytes -= self._slice_bytes
            self._evicted += 1
            self._files_to_remove.append(rel)

    def _deregister(self, rel_paths: Iterable[str]) -> None:
        """Drop blocks from tracking and queue their deletion on every rank."""
        for rel in rel_paths:
            if rel in self._lru:
                del self._lru[rel]
                self._bytes -= self._slice_bytes
            self._files_to_remove.append(rel)

    # -- connector-scheduler interface (beyond SecondaryTierManager) -------

    def drain_worker_directives(
        self,
    ) -> tuple[list[DiskJobDirective], list[str]]:
        """Hand the queued disk jobs and deletions to the connector scheduler.

        Called once per step from build_connector_meta(); the result is
        broadcast to every worker in this step's connector metadata.
        """
        directives, self._directives = self._directives, []
        removes, self._files_to_remove = self._files_to_remove, []
        return directives, removes

    def note_worker_reports(
        self, completed: dict[int, int], failed: dict[int, int]
    ) -> None:
        """Feed per-rank completion reports back into job tracking.

        Called from update_connector_output(). Counts are per job id and sum
        across ranks; a job finalizes when reports reach the world size.
        Unknown ids (another tier's, or stale) are ignored.
        """
        for reports, is_failure in ((completed, False), (failed, True)):
            for job_id, count in reports.items():
                job = self._pending_jobs.get(job_id)
                if job is None:
                    continue
                job.reports += count
                if is_failure:
                    job.failures += count
                if job.reports < self._num_workers:
                    continue
                del self._pending_jobs[job_id]
                self._finalize_job(job_id, job)

    def _finalize_job(self, job_id: int, job: _PendingJob) -> None:
        success = job.failures == 0
        if job.is_load:
            for rel in job.rel_paths:
                refs = self._load_refs.get(rel, 0) - 1
                if refs > 0:
                    self._load_refs[rel] = refs
                else:
                    self._load_refs.pop(rel, None)
            if not success:
                logger.warning(
                    "fs_lru: disk load job %d failed on >=1 rank; "
                    "deregistering %d block(s), prefix will be recomputed",
                    job_id,
                    len(job.rel_paths),
                )
                self._deregister(job.rel_paths)
        else:
            if success:
                for rel in job.rel_paths:
                    if self._lru.get(rel) == _STORING:
                        self._lru[rel] = _READY
            else:
                logger.warning(
                    "fs_lru: disk store job %d failed on >=1 rank; "
                    "deregistering %d block(s)",
                    job_id,
                    len(job.rel_paths),
                )
                self._deregister(job.rel_paths)
        self._finished.append(JobResult(job_id=job_id, success=success))

    # -- SecondaryTierManager interface ------------------------------------

    @override
    def lookup(self, key: OffloadKey, req_context: ReqContext) -> bool | None:
        state = self._lru.get(self._rel_path(key))
        if state == _READY:
            self._lookup_hits += 1
            return True
        if state == _STORING:
            # The store has not completed on every rank yet; the scheduler
            # re-asks on a later step.
            self._lookup_pending += 1
            return None
        self._lookup_misses += 1
        return False

    @override
    def submit_store(self, job_metadata: JobMetadata) -> None:
        rel_paths = [self._rel_path(key) for key in job_metadata.keys]
        for rel in rel_paths:
            if rel in self._lru:
                self._lru.move_to_end(rel)
            else:
                self._lru[rel] = _STORING
                self._bytes += self._slice_bytes
        self._evict(keep=frozenset(rel_paths))

        # Ship EVERY block, not just the new ones: the worker-side write
        # skips files that already exist, so re-sending known blocks is
        # nearly free and heals a rank that lost one.
        self._directives.append(
            DiskJobDirective(
                job_id=job_metadata.job_id,
                is_load=False,
                blocks=[
                    (rel, int(bid))
                    for rel, bid in zip(rel_paths, job_metadata.block_ids)
                ],
            )
        )
        self._pending_jobs[job_metadata.job_id] = _PendingJob(
            is_load=False, rel_paths=rel_paths
        )

    @override
    def submit_load(self, job_metadata: JobMetadata) -> None:
        rel_paths = [self._rel_path(key) for key in job_metadata.keys]
        n = len(rel_paths)
        self._loaded_blocks += n
        logger.info(
            "fs_lru: reading %d block(s) (%.1f MiB per rank) from disk "
            "for request %s",
            n,
            n * self._slice_bytes / (1 << 20),
            job_metadata.req_context.req_id,
        )
        for rel in rel_paths:
            if rel in self._lru:
                self._lru.move_to_end(rel)
            self._load_refs[rel] = self._load_refs.get(rel, 0) + 1

        self._directives.append(
            DiskJobDirective(
                job_id=job_metadata.job_id,
                is_load=True,
                blocks=[
                    (rel, int(bid))
                    for rel, bid in zip(rel_paths, job_metadata.block_ids)
                ],
            )
        )
        self._pending_jobs[job_metadata.job_id] = _PendingJob(
            is_load=True, rel_paths=rel_paths
        )

    @override
    def get_finished_jobs(self) -> Iterable[JobResult]:
        finished, self._finished = self._finished, []
        return finished

    @override
    def touch(self, keys, req_context: ReqContext):
        for key in keys:
            rel = self._rel_path(key)
            if rel in self._lru:
                self._lru.move_to_end(rel)

    @override
    def on_new_request(self, req_context: ReqContext) -> RequestOffloadingContext:
        self._req_marks[req_context.req_id] = (
            self._lookup_hits,
            self._lookup_misses,
            self._lookup_pending,
        )
        return RequestOffloadingContext()

    @override
    def on_request_finished(self, req_context: ReqContext) -> None:
        mark = self._req_marks.pop(req_context.req_id, None)
        if mark is not None:
            hits = self._lookup_hits - mark[0]
            misses = self._lookup_misses - mark[1]
            pending = self._lookup_pending - mark[2]
            if hits or misses or pending:
                total = hits + misses
                rate = (100.0 * hits / total) if total else 0.0
                logger.info(
                    "fs_lru[%s]: disk cache %d hit / %d miss (%.1f%%), "
                    "%d deferred; %d blocks loaded from disk this run",
                    req_context.req_id,
                    hits,
                    misses,
                    rate,
                    pending,
                    self._loaded_blocks,
                )

    @override
    def shutdown(self) -> None:
        logger.info(
            "fs_lru: %.2f GiB of %.2f GiB per-rank cap in use, "
            "%d blocks evicted this run",
            self._bytes / (1 << 30),
            self._max_bytes / (1 << 30),
            self._evicted,
        )
